inline void line_kinematics(
    const mat3 &H, const vec3 &fp, const vec3 &fpp,
    const mat3 &H_dot,
    vec3 &g_dot, vec3 &g_ddot) {
  g_dot = H * fp;
  g_ddot = H_dot * fp + H * fpp;
}

inline real newton_step_t(
    real t, real E_prime, real E_pp,
    real min_denom = 1e-14, real lm_lambda = 1e-8, real grad_scale = 0.1) {
  if (std::abs(E_pp) >= min_denom) return t - E_prime / E_pp;
  if (std::abs(E_prime) < 1e-14) return t;
  return t - grad_scale * E_prime;
}

template <typename GeometryBundle, typename LineBundle>
inline void eval_medial_energy_at_t(
    const GeometryBundle &geom, const LineBundle &line, real t,
    real &E, real &E_prime, real &E_pp,
    real eps = 1e-12) {
  const vec3 x = line.f(t);
  const vec3 fp = line.fp(t);
  const vec3 fpp = line.fpp(t);
  const vec3 g = geom.G(x);
  const mat3 H = geom.H(x);
  const mat3 H_dot = geom.H_directional(x, fp);
  const mat3 H_ddot = geom.H_directional_rate(x, fp, fpp);
  vec3 g_dot, g_ddot;
  line_kinematics(H, fp, fpp, H_dot, g_dot, g_ddot);
  inv_frob_derivs_from_kinematics(
      g, H, g_dot, H_dot, g_ddot, H_ddot, E, E_prime, E_pp, eps);
}

